import{_ as l,o as i,c as e,a2 as o}from"./chunks/framework.BG8d4IEm.js";const u=JSON.parse('{"title":"技术学习方法论","description":"","frontmatter":{"tags":["方法论"]},"headers":[],"relativePath":"posts/2017-02-09-how_to_learning_language.md","filePath":"posts/2017-02-09-how_to_learning_language.md"}'),t={name:"posts/2017-02-09-how_to_learning_language.md"};function r(n,a,s,h,d,_){return i(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="技术学习方法论" tabindex="-1">技术学习方法论 <a class="header-anchor" href="#技术学习方法论" aria-label="Permalink to &quot;技术学习方法论&quot;">​</a></h1><p><strong>技术学习的目的方法等</strong></p><hr><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>在学习繁杂的 web 技术过程中，有时会陷入一定的焦虑，焦虑的问题如下！</p><ol><li>如何选择技术栈？</li><li>如何快速上手一门技术？</li><li>学会一门技术到精通一门技术的考量标准到底是什么？</li><li>如何成为专家级的技术人员？ ...</li></ol><h2 id="技术的阶段性" tabindex="-1">技术的阶段性 <a class="header-anchor" href="#技术的阶段性" aria-label="Permalink to &quot;技术的阶段性&quot;">​</a></h2><ol><li>听过但是忘了</li><li>见过还记得</li><li>做过且理解</li></ol><h2 id="如何选择技术栈" tabindex="-1">如何选择技术栈 <a class="header-anchor" href="#如何选择技术栈" aria-label="Permalink to &quot;如何选择技术栈&quot;">​</a></h2><h2 id="学习模式" tabindex="-1">学习模式 <a class="header-anchor" href="#学习模式" aria-label="Permalink to &quot;学习模式&quot;">​</a></h2><p>通过阅读有些的博文总结出了一些内在的规律性。</p><ol><li><strong>套路化</strong> 有详细的操作流程和操作步骤，具有逻辑性和条理性。</li><li><strong>阶梯性</strong><br> 讲解的方式符合认知规律，都是从最基本的概念入手，逐层递进，实现对知识的整理和讲解。</li><li><strong>模块性</strong><br> 自成体系，有独立成章，整片文章具有弱相关和强独立，这就意味着对于不同层级的阅读者，能够提供多样的阅读体验。</li></ol><h2 id="学习问题" tabindex="-1">学习问题 <a class="header-anchor" href="#学习问题" aria-label="Permalink to &quot;学习问题&quot;">​</a></h2><ol><li>建立基础认知，这是第一个阶段学会用</li><li>建立场景，这是目前最缺乏的东西，每次，学完都没有绑定典型情景,导致基本认知出现断裂。需要进行如下强化。 <ol><li>总结典型应用场景</li><li>积累共性场景和模式</li><li>精简优化场景形成模板</li></ol></li><li>建立场景化后需要进一步进行系统级构建 <ol><li>场景的组合使用</li><li>建立场景模式的搭建原则</li></ol></li></ol><h2 id="递归原则" tabindex="-1">递归原则 <a class="header-anchor" href="#递归原则" aria-label="Permalink to &quot;递归原则&quot;">​</a></h2><ol><li>从基本层级开始</li><li>深化一个层级</li><li>实现递归</li></ol><h2 id="读源码" tabindex="-1">读源码 <a class="header-anchor" href="#读源码" aria-label="Permalink to &quot;读源码&quot;">​</a></h2><p>弄清楚设计思路，进行检索。</p>',18)])])}const g=l(t,[["render",r]]);export{u as __pageData,g as default};
